/**
 * EDITH Deterministic ID Generator (code-nodes/make_ids.js)
 */
const crypto = require('crypto');

function sha256(str) {
  return crypto.createHash('sha256').update(str, 'utf8').digest('hex');
}

function normaliseTranscriptForHashing(text) {
  return (text || '')
    .toLowerCase()
    .replace(/\[\s*\d{1,2}:\d{2}(?::\d{2})?(?:\s*[apap][mm])?\s*\]/g, '')
    .replace(/\(\s*\d{1,2}:\d{2}(?::\d{2})?(?:\s*[apap][mm])?\s*\)/g, '')
    .replace(/^\s*\d{1,2}:\d{2}(?::\d{2})?(?:\s*[apap][mm])?\s+/gm, '')
    .replace(/\s+/g, ' ')
    .trim();
}

const items = $input.all();
const results = [];

for (const item of items) {
  const json = item.json;
  const rawText = json.normalised_text || json.original_text || json.text || '';
  const chatId = String(json.chat_id || '');

  const normalisedForHash = normaliseTranscriptForHashing(rawText);
  const transcriptHash = sha256(normalisedForHash + chatId);
  const meetingId = 'MTG-' + transcriptHash.substring(0, 8).toUpperCase();

  results.push({
    json: {
      ...json,
      transcript_hash: transcriptHash,
      meeting_id: meetingId,
      normalised_for_hash: normalisedForHash,
      retry_count: 0
    }
  });
}

return results;

/**
 * Evaluate Transcript Duplicate against Meetings Tab
 */
const items = $input.all();
const results = [];
const makeIdsData = $('Compute Deterministic IDs & Hash').first()?.json || {};
const currentHash = makeIdsData.transcript_hash || '';
const chatId = makeIdsData.chat_id;

const existingMeetings = items.map(i => i.json);
const match = existingMeetings.find(m => m.transcript_hash === currentHash);

if (match) {
  results.push({
    json: {
      is_duplicate: true,
      transcript_hash: currentHash,
      chat_id: chatId,
      existing_meeting_id: match.meeting_id || 'UNKNOWN',
