/**
 * EDITH Split Clarification Dispatches (code-nodes/split_clarification_dispatches.js)
 * 
 * Flattens array of clarification messages into individual n8n items
 * so the Telegram node sends a dedicated message with inline buttons
 * for each incomplete task.
 */

const items = $input.all();
const results = [];

for (const item of items) {
  const dispatches = item.json.clarification_dispatches || [];
  for (const d of dispatches) {
    results.push({
      json: {
        chat_id: d.chat_id,
        task_id: d.task_id,
        text: d.text,
        reply_markup: d.reply_markup
      }
    });
  }
}

return results;

/**
 * EDITH Meeting Memory & Open Tasks Extractor (code-nodes/extract_meeting_memory.js)
 */
const items = $input.all();
const results = [];

let meetings = [];
try {
  meetings = $('Read Meetings Tab').all().map(i => i.json);
} catch (e) {
  meetings = [];
}

let tasks = [];
try {
  tasks = $('Read ActionItems Tab (Memory)').all().map(i => i.json);
} catch (e) {
  tasks = [];
}

for (const item of items) {
  const json = item.json;
  const chatId = String(json.chat_id || '');

  // 1. Filter meetings for this specific chat
  const chatMeetings = meetings.filter(m => String(m.chat_id || '') === chatId);

  let memoryContext = 'Earlier Open Tasks: None recorded from previous meetings.';
  if (chatMeetings.length > 0) {
    // Sort by meeting_date descending and take up to 3
    const sorted = [...chatMeetings].sort((a, b) => {
      const dateA = a.meeting_date || a.processed_at || '';
      const dateB = b.meeting_date || b.processed_at || '';
      return String(dateB).localeCompare(String(dateA));
    });

    const last3MeetingIds = new Set(sorted.slice(0, 3).map(m => m.meeting_id).filter(Boolean));

    const openTasks = tasks.filter(t => {
      if (!last3MeetingIds.has(t.meeting_id)) return false;
      const status = (t.status || '').toLowerCase().trim();
      return status !== 'completed';
    });

    if (openTasks.length > 0) {
      memoryContext = 'Earlier Open Tasks (from recent meetings of this group):\n';
      openTasks.forEach(t => {
        const ownerStr = t.owner || 'Unassigned';
        const tgStr = t.owner_telegram_id ? ` (${t.owner_telegram_id})` : '';
        const deadlineStr = t.deadline || t.deadline_phrase || 'No deadline';
        memoryContext += `- [${t.task_id}] "${t.task}" | Owner: ${ownerStr}${tgStr} | Status: ${t.status} | Deadline: ${deadlineStr}\n`;
      });
      memoryContext = memoryContext.trim();
    }
  }

  results.push({
    json: {
      ...json,
      earlier_tasks_context: memoryContext
    }
  });
}

return results;
